function minPath(grid, k) {
    const N = grid.length;
    let visited = new Array(N).fill(false).map(() => new Array(N).fill(false));
    let directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPathValues = [];

    function dfs(row, col, steps) {
        if (steps === k) {
            minPathValues.push(...grid[row][col]);
            return;
        }

        visited[row][col] = true;

        for (let dir of directions) {
            const newRow = row + dir[0];
            const newCol = col + dir[1];

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                dfs(newRow, newCol, steps + 1);
            }
        }

        visited[row][col] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                dfs(i, j, 1);
            }
        }
    }

    return minPathValues.sort((a, b) => a - b);
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPathValues = [];
    let visited = new Array(N).fill(false).map(() => new Array(N).fill(false));

    function dfs(x, y, steps, path) {
        if (steps === k) {
            minPathValues.push(path.slice());
            return;
        }

        for (let i = 0; i < directions.length; i++) {
            const nx = x + directions[i][0];
            const ny = y + directions[i][1];

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, steps + 1, path.concat(grid[nx][ny]));
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    minPathValues.sort((a, b) => a.join('') < b.join('') ? -1 : 1);
    return minPathValues[0];
}

