function find_First_Missing(array) {
  let start = 0;
  let end = array.length - 1;

  while (start <= end) {
    let mid = Math.floor((start + end) / 2);

    if (array[mid] === mid + 1) {
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  return start + 1;
}

