function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to the range [0, 1]
    r = r / 255;
    g = g / 255;
    b = b / 255;

    // Find the maximum and minimum values in the RGB array
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the value (V)
    let v = max;

    // Calculate the saturation (S)
    let s = 0;
    if (v !== 0) {
        s = (max - min) / v;
    }

    // Calculate the hue (H)
    let h = 0;
    if (s !== 0) {
        let delta = max - min;

        if (r === max) {
            h = (g - b) / delta;
        } else if (g === max) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }

        // Normalize hue to the range [0, 360]
        h *= 60;
        if (h < 0) {
            h += 360;
        }
    }

    return { h: h, s: s, v: v };
}

