  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the difference between max and min
  let delta = max - min;

  // Calculate the hue (H)
  let h;
  if (delta === 0) {
    h = 0;
  } else if (max === r) {
    h = ((g - b) / delta) % 6;
  } else if (max === g) {
    h = ((b - r) / delta + 2) % 6;
  } else {
    h = ((r - g) / delta + 4) % 6;
  }

  // Calculate the saturation (S)
  let s;
  if (delta === 0) {
    s = 0;
  } else {
    s = delta / max;
  }

  // Calculate the value (V)
