function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  let digits = n.toString().split('');

  // Start from the second last digit and move towards the first digit
  for (let i = digits.length - 2; i >= 0; i--) {
    // If the current digit is less than the digit immediately after it
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right of the current digit that is greater than it
      let j = i + 1;
      while (j < digits.length && digits[j] <= digits[i]) {
        j++;
      }

      // Swap the found digits
      [digits[i], digits[j - 1]] = [digits[j - 1], digits[i]];

      // Sort the remaining digits in ascending order
      digits.sort((a, b) => a - b);

      // Return the rearranged number as an integer
      return parseInt(digits.join(''));
    }
  }

  // If no such arrangement is possible, return -1
  return -1;
}

