        if (digits[i] < digits[i + 1]) break;
    }

    // If no such digit is found, return null since no bigger number can be formed
    if (i === -1) return null;

    // Find the smallest digit to the right of the found digit that is greater than it
    let j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) break;
    }

    // Swap the found digits
