function min_Jumps(steps, d){
    // Calculate the absolute difference between the starting position and the target position
    const diff = Math.abs(d);

    // If the difference is less than or equal to steps, no jumps are needed
    if (diff <= steps) {
        return 1;
    }

    // Otherwise, calculate the number of jumps required
    let jumps = 0;
    while (diff > 0) {
        diff -= steps;
        jumps++;
    }

    return jumps;
}

