function find_length(string) {
    let maxDiff = 0;
    let countZeros = 0;
    let countOnes = 0;

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '0') {
            countZeros++;
        } else {
            countOnes++;
        }

        const currentDiff = Math.abs(countZeros - countOnes);
        maxDiff = Math.max(maxDiff, currentDiff);

        // Reset counts if the difference exceeds 1
        if (currentDiff > 1) {
            countZeros = 0;
            countOnes = 0;
        }
    }

    return maxDiff;
}

function find_length(string) {
    let maxDiff = 0;
    let countZeroes = 0;
    let countOnes = 0;

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '0') {
            countZeroes++;
        } else {
            countOnes++;
        }

        const currentDiff = Math.abs(countZeroes - countOnes);
        maxDiff = Math.max(maxDiff, currentDiff);

        // If the difference exceeds half of the length of the string, reset counts
        if (currentDiff > string.length / 2) {
            countZeroes = 0;
            countOnes = 0;
        }
    }

    return maxDiff;
}

