function heap_sort(iterable) {
    // Helper function to swap two elements in an array
    function swap(arr, i, j) {
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }

    // Helper function to heapify a subtree rooted at index i with parent index p
    function heapify(arr, n, i, p) {
        let largest = i;
        const left = 2 * i + 1;
        const right = 2 * i + 2;

        if (left < n && arr[left] > arr[largest]) {
            largest = left;
        }

        if (right < n && arr[right] > arr[largest]) {
            largest = right;
        }

        if (largest !== i) {
            swap(arr, i, largest);
            heapify(arr, n, largest, p);
        }
    }

    // Build a max-heap from the array
    for (let i = Math.floor(iterable.length / 2 - 1); i >= 0; i--) {
        heapify(iterable, iterable.length, i, null);
    }

    // Sort the array using heap sort
    for (let i = iterable.length - 1; i > 0; i--) {
        swap(iterable, 0, i);
        heapify(iterable, i, 0, null);
    }

    return iterable;
}

